import numpy as np


def init_loss(seed):
    rng = np.random.default_rng(seed)
    w = {}
    for name, shape in expected_shapes(CFG).items():
        if name.endswith('_g'):
            w[name] = np.ones(shape)
        elif len(shape) == 1:
            w[name] = np.zeros(shape)
        else:
            w[name] = rng.standard_normal(shape) * 0.02
    return model_loss(w, XB, YB)

