import numpy as np
from gpt_ops_l2 import encode, mean_loss as model_loss, shapes as _sh

CFG = {'V': 65, 'T': 32, 'd': 32, 'n_head': 4, 'n_layer': 1, 'mlp': 128}


def expected_shapes(config):
    return dict(_sh(config))


_v = np.array(encode(open('tiny-shakespeare.txt').read()[225000:]))
XB = _v[:512].reshape(16, 32)
YB = _v[1:513].reshape(16, 32)

